import java.util.*;
import java.io.*;

public class Main {
    static long[][] comb = new long[62][62];
    static long[][] A = new long[32][32];
    static long[][] B = new long[32][32];
    static long totalComb;
    static int row, col, total;
    static String pattern;
    static long[][] countComb = new long[32][32];
    static long maxDiff;
    static List<Pair>[][] P = new ArrayList[32][2];
    static List<Pair>[][] Q = new ArrayList[32][2];
    static long totalResult = 0;

    static class Pair implements Comparable<Pair> {
        long first;
        long second;

        Pair(long first, long second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public int compareTo(Pair o) {
            return Long.compare(this.first, o.first);
        }
    }

    static void addPath(int x, int y, long g, long c1, long c2, int ck) {
        if (x + y == row + total) {
            P[x][ck].add(new Pair(g, c1));
            if (c2 != 0) Q[x][ck].add(new Pair(g, c2));
            return;
        }
        addPath(x + 1, y, g + (!ck ? A[x + 1][y] : 0), c1, (pattern.charAt(x + y) != 'B' ? c2 : 0), ck);
        addPath(x, y + 1, g + (ck ? B[x][y + 1] : 0), c1, (pattern.charAt(x + y) != 'A' ? c2 : 0), ck);
    }

    static void computeMin(int x, int y, long g, int ck) {
        if (x + y == row + total) {
            if (P[x][ck].isEmpty()) return;
            int t = lowerBound(P[x][ck], new Pair((totalComb + 1) / 2 - g, 0));
            if (t != P[x][ck].size() && P[x][ck].get(t).second > 0) {
                long tp = (P[x][ck].get(t).first + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (maxDiff > tp) maxDiff = tp;
            }
            if (t > 0 && P[x][ck].get(t - 1).second > 0) {
                long tp = (P[x][ck].get(t - 1).first + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (maxDiff > tp) maxDiff = tp;
            }
            return;
        }
        computeMin(x - 1, y, g + (!ck ? A[x][y] : 0), ck);
        computeMin(x, y - 1, g + (ck ? B[x][y] : 0), ck);
    }

    static void computeMax(int x, int y, long g, int ck) {
        if (x + y == row + total) {
            int t = lowerBound(Q[x][ck], new Pair((totalComb + 1) / 2 - g, 0));
            if (t != Q[x][ck].size() && Q[x][ck].get(t).second > 0) {
                long tp = (Q[x][ck].get(t).first + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (maxDiff == tp) {
                    totalResult += Q[x][ck].get(t).second;
                }
            }
            if (t > 0 && Q[x][ck].get(t - 1).second > 0) {
                long tp = (Q[x][ck].get(t - 1).first + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (maxDiff == tp) {
                    totalResult += Q[x][ck].get(t - 1).second;
                }
            }
            return;
        }
        if (pattern.charAt(x + y - 1) != 'B') computeMax(x - 1, y, g + (!ck ? A[x][y] : 0), ck);
        if (pattern.charAt(x + y - 1) != 'A') computeMax(x, y - 1, g + (ck ? B[x][y] : 0), ck);
    }

    static void compress(List<Pair> P) {
        if (P.isEmpty()) return;
        Collections.sort(P);
        int count = 0;
        long sum = 0;
        for (int i = 0; i < P.size(); i++) {
            sum += P.get(i).second;
            if (i == P.size() - 1 || P.get(i).first != P.get(i + 1).first) {
                P.set(count, new Pair(P.get(i).first, sum));
                count++;
                sum = 0;
            }
        }
        while (P.size() > count) {
            P.remove(P.size() - 1);
        }
    }

    static int lowerBound(List<Pair> list, Pair key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid).compareTo(key) < 0) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        row = Integer.parseInt(st.nextToken());
        col = Integer.parseInt(st.nextToken());
        pattern = br.readLine();

        for (int i = 0; i <= 61; i++) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }

        total = row + col;
        totalComb = comb[total * 2][row * 2];

        for (int i = 0; i <= total; i++) {
            for (int j = 0; j <= total; j++) {
                if (i > 0) A[i][j] = comb[i - 1][row - 1] * (comb[total * 2 - i][row] - comb[j][row]);
                if (j > 0) B[i][j] = comb[j - 1][row - 1] * (comb[total * 2 - j][row] - comb[i][row]);
            }
        }

        for (int i = 0; i <= total; i++) {
            for (int j = 0; j < 2; j++) {
                P[i][j] = new ArrayList<>();
                Q[i][j] = new ArrayList<>();
            }
        }

        for (int i = row; i <= total; i++) {
            if (pattern.charAt(i + row - 1) != 'B') addPath(row, i, A[row][i], comb[i + row - 1][row - 1], countComb[row - 1][i], 0);
            if (pattern.charAt(i + row - 1) != 'A') addPath(i, row, B[i][row], comb[i + row - 1][row - 1], countComb[i][row - 1], 1);
        }

        for (int i = row; i <= total; i++) {
            for (int j = 0; j < 2; j++) {
                compress(P[i][j]);
                compress(Q[i][j]);
            }
        }

        maxDiff = totalComb + 1;
        computeMin(total, total, 0, 0);
        computeMin(total, total, 0, 1);
        computeMax(total, total, 0, 0);
        computeMax(total, total, 0, 1);

        System.out.println(totalResult);
    }
}
